{"meetingId": "409", "tickets": [
{"title": "Collect Client Tax Documents", "text": "Request and organize current tax documents for planning review, including prior-year federal and state returns, W-2s, 1099s, K-1s, estimated tax payment records, charitable giving summaries, and any tax notices. Track missing items and route complete packet to the planning team. For Anika Pebblefizz, obtain the missing Velvet Acorn consolidated tax form and charitable giving summary that Beren Nettlewhisk of Paper Otter Tax Services requested for the IRS notice review on the 2022 federal return proposing $3,186 of additional tax and interest.", "priority": "medium", "dueDate": "2024-04-18", "assigneeId": "405a0bba-bb14-5076-904a-cb26172e4fcb", "subTasks": [], "templateId": "ca0beb64-4823-5deb-8d28-1f7a5f7d128e", "evidence": "the agreed follow-up is to obtain those records by April 18, 2024"},
{"title": "Resolve custodian dividend income variance", "text": "Reconcile the $14,860 of ordinary dividends from the Velvet Acorn taxable account listed in the IRS correspondence against the $7,440 shown on the 2022 return worksheet for Anika Pebblefizz, and document the correct figure before the notice response is finalized.", "priority": null, "dueDate": "2024-04-24", "assigneeId": null, "subTasks": [], "templateId": null, "evidence": "resolution of the custodian income variance is needed by April 24, 2024"},
{"title": "Send tax notice records to CPA securely", "text": "Send only the IRS notice, relevant tax forms, and account statements for Anika Pebblefizz to Beren Nettlewhisk of Paper Otter Tax Services through secure delivery, per her authorization, excluding any other documents.", "priority": null, "dueDate": "2024-04-16", "assigneeId": null, "subTasks": [], "templateId": null, "evidence": "Anika authorized coordination with Beren and requested that only the notice, relevant tax forms, and account statements be sent through secure delivery by April 16, 2024."}
]}
